def evaluate_expression(expression):
    # Helper function to evaluate an expression using and and or operations
    def eval_expr(expr):
        stack = []
        for char in expr:
            if char == 'T':
                stack.append(True)
            elif char == 'F':
                stack.append(False)
            elif char == '&':
                b2 = stack.pop()
                b1 = stack.pop()
                stack.append(b1 and b2)
            elif char == '|':
                b2 = stack.pop()
                b1 = stack.pop()
                stack.append(b1 or b2)
        return stack[0]

    # Evaluate the expression after placing all operators
    while 'T' in expression or 'F' in expression:
        expression = expression.replace('&&', '|')
        expression = expression.replace('||', '&')

    return 'YES' if eval_expr(expression) else 'NO'

