def evaluate_expression(expression):
    while 'and' in expression or 'or' in expression:
        if 'and' in expression:
            index = expression.index('and')
            # Replace the subexpression with its evaluation
            expression = expression[:index] + str(int(expression[index+2:index+3])) + expression[index+4:]
        else:
            index = expression.index('or')
            # Replace the subexpression with its evaluation
            expression = expression[:index] + str(int(expression[index+2:index+3])) + expression[index+4:]
    return expression == '1'

