import sys

def is_alice_wins(binary_string):
    def evaluate_expression(expression):
        stack = []
        for char in expression:
            if char == '1':
                stack.append(char)
            elif char == '0':
                if len(stack) > 0:
                    stack.pop()
            elif char == '&':
                if len(stack) < 2:
                    return False
                left = int(stack.pop())
                right = int(stack.pop())
                stack.append('1' if left and right else '0')
            elif char == '|':
                if len(stack) < 2:
                    return True
                left = int(stack.pop())
                right = int(stack.pop())
                stack.append('1' if left or right else '0')
        return stack[0] == '1'

    # Convert binary string to list of integers
    binary_list = [int(bit) for bit in binary_string]

    # Start with Alice's turn
    alice_turn = True

    # Iterate through the binary list
    for i in range(len(binary_list)):
        # Check if it's Alice's turn
        if alice_turn:
            # Place an and operator
            binary_list[i] &= binary_list[i + 1]
            # Switch to Bob's turn
            alice_turn = False
        else:
            # Place an or operator
            binary_list[i] |= binary_list[i + 1]
            # Switch to Alice's turn
            alice_turn = True

    # Evaluate the final expression
    return evaluate_expression(''.join(map(str, binary_list)))

