def optimal_boolean_game(n, binary_string):
    # Initialize the game state
    current_state = binary_string

    # Function to evaluate the current state
    def evaluate_state(state):
        if '0' not in state:
            return True
        if '1' not in state:
            return False

        # Split the state into substrings based on '0'
        parts = state.split('0')

        # Evaluate each part using recursion
        for part in parts:
            if part == '':
                continue
            if evaluate_state(part):
                return True
            elif evaluate_state(part) == False:
                return False

        return False

    # Determine the winner based on the initial state
    if evaluate_state(current_state):
        return "YES"
    else:
        return "NO"

