def perimeter(x, y, m):
    visited = [[False] * m for _ in range(m)]
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    count = 0

    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= m or visited[i][j]:
            return
        visited[i][j] = True
        count += 1

        for dx, dy in directions:
            nx, ny = i + dx, j + dy
            dfs(nx, ny)

    for xi, yi in zip(x, y):
        for dx, dy in directions:
            nx, ny = xi + dx, yi + dy
            while 0 <= nx < m and 0 <= ny < m and not visited[nx][ny]:
                dfs(nx, ny)
                nx, ny = nx + dx, ny + dy

    return count * 4 - (len(x) - count) * 2

