def perimeter_of_shape(n, m, x, y):
    visited = [[False] * m for _ in range(m)]
    stack = []

    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= m or visited[x][y]:
            return
        visited[x][y] = True
        stack.append((x, y))

        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            dfs(x + dx, y + dy)

    perimeter = 0

    for i in range(n):
        x_new, y_new = x[i], y[i]
        if x_new == 0 or y_new == 0 or x_new == m - 1 or y_new == m - 1:
            continue

        if not visited[x_new][y_new]:
            dfs(x_new, y_new)
            perimeter += 4

            # Check adjacent cells
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = x_new + dx, y_new + dy
                if nx < 0 or nx >= m or ny < 0 or ny >= m or visited[nx][ny]:
                    perimeter -= 1

    return perimeter

