def swap_columns(matrix, col1, col2):
    # Swap columns col1 and col2 in the matrix
    matrix[0][:col1], matrix[0][col2] = matrix[0][col2], matrix[0][:col1]
    matrix[1][:col1], matrix[1][col2] = matrix[1][col2], matrix[1][:col1]

def max_path_cost(n, matrix1, matrix2):
    # Calculate the cost of a path starting from (1,1) to (2,n)
    cost = 0
    current_row, current_col = 1, 1
    while current_row != 2 or current_col != n:
        if current_col == n:
            current_row += 1
        elif current_row == 2:
            current_col += 1
        else:
            # Choose the next cell based on the current position
            if current_col < n:
                next_cell = (current_row, current_col + 1)
            else:
                next_cell = (current_row + 1, current_col)
            cost += min(matrix1[current_row][current_col], matrix2[next_cell[0]][next_cell[1]])
            current_row, current_col = next_cell
    return cost

