def calculate_day(n, a, b, c):
    # Calculate the total distance covered after 'i' days
    def total_distance(i):
        return i * (a + b + c)

    # Binary search to find the minimum 'i' such that total_distance(i) >= n
    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        if total_distance(mid) >= n:
            right = mid
        else:
            left = mid + 1

    return left

