def binomial_coefficient(n, k):
    # Base case: C(n, 0) = 1
    if k == 0:
        return 1
    # Base case: C(n, n) = 1
    if k == n:
        return 1
    # Calculate C(n, k) using Pascal's Triangle formula
    result = 1
    for i in range(k):
        result *= (n - i)
        result //= (i + 1)
    return result % (10**9 + 7)

