def is_winning(n, a, b):
    # Check if the frogs are already on the same position
    if a == b:
        return False

    # Determine the parity of the positions of Alice and Bob
    alice_parity = a % 2
    bob_parity = b % 2

    # If they have different parities, Alice can always force Bob into a losing position
    if alice_parity != bob_parity:
        return True

    # If they have the same parity, Alice cannot force Bob into a losing position
    else:
        return False

