def max_sum_after_operations(n, a):
    if n == 1:
        return a[0]

    # If the sequence is already sorted in non-decreasing order,
    # we can reverse it to maximize the sum of differences.
    if sorted(a) == a:
        return sum(a)

    # Otherwise, we need to find the best way to maximize the sum of differences.
    # We can do this by reversing the sequence and replacing it with its difference sequence.
    reversed_a = a[::-1]
    diff_a = [reversed_a[i+1] - reversed_a[i] for i in range(len(reversed_a)-1)]

    return sum(diff_a)

