def find_valid_string(s):
    n = len(s)
    count = [0] * 26
    for i in range(n):
        count[ord(s[i]) - ord('a')] += 1

    odd_count = sum(1 for c in count if c % 2 != 0)

    if odd_count > 1:
        return -1

    if odd_count == 1:
        for i in range(n):
            if count[ord(s[i]) - ord('a')] % 2 != 0:
                # Find a character with odd count and replace it with 'a'
                for j in range(26):
                    if count[j] % 2 == 0:
                        s[i] = chr(j + ord('a'))
                        break
                return s

    return s

