def min_operations_to_one(a):
    if len(a) == 1:
        return 1

    operations = 0
    left = 0
    right = 0

    while right < len(a):
        if a[right] == 0:
            a[left] = 1
            left += 1
            right += 1
        else:
            right += 1

    if left != len(a):
        operations += len(a) - left

    return operations

