def min_perimeter(n, stamps):
    # Initialize the grid with all cells being white
    grid = [[0] * 100 for _ in range(100)]

    # Place the stamps on the grid
    for i in range(n):
        w, h = stamps[i]
        for x in range(100 - w + 1):
            for y in range(100 - h + 1):
                grid[x][y] += 1

    # Find the connected components and calculate their perimeters
    def dfs(x, y, visited):
        visited.add((x, y))
        perimeter = 0
        for dx, dy in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < 100 and 0 <= ny < 100 and grid[nx][ny] > 0 and (nx, ny) not in visited:
                perimeter += 4
                dfs(nx, ny, visited)
        return perimeter

    connected_components = []
    for i in range(100):
        for j in range(100):
            if grid[i][j] > 0 and (i, j) not in visited:
                visited = set()
                perimeter = dfs(i, j, visited)
                connected_components.append(perimeter)

    # Return the minimum perimeter among the connected components
    return min(connected_components)

