def min_perimeter(n, stamps):
    # Initialize the grid with zeros
    grid = [[0] * n for _ in range(n)]

    # Place the stamps on the grid
    for i in range(n):
        for j in range(n):
            for w, h in stamps:
                if i + w <= n and j + h <= n:
                    for x in range(i, i + w):
                        for y in range(j, j + h):
                            grid[x][y] = 1

    # Calculate the perimeter of each connected component
    visited = [[False] * n for _ in range(n)]
    def dfs(x, y):
        if visited[x][y]:
            return 0
        visited[x][y] = True
        perimeter = 0
        directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 1:
                perimeter += 1
                perimeter += dfs(nx, ny)
        return perimeter

    total_perimeter = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                total_perimeter += dfs(i, j)

    return total_perimeter

