def count_minimal_coprimes(l, r):
    # Initialize the result counter
    result = 0

    # Iterate over all possible starting points for the segment
    for start in range(1, r + 1):
        # Iterate over all possible ending points for the segment
        for end in range(start, r + 1):
            # Check if the current segment [start, end] is coprime
            if gcd(start, end) == 1:
                # Check if the current segment does not contain any other coprime segment not equal to itself
                is_minimal = True
                for i in range(start + 1, end):
                    if gcd(i, end) != 1:
                        is_minimal = False
                        break
                if is_minimal:
                    result += 1

    return result

