    freq = {}
    for i in range(l, r + 1):
        if i in freq:
            freq[i] += 1
        else:
            freq[i] = 1

    # Find the largest number whose frequency is greater than or equal to k
    max_freq_num = None
    max_freq = 0
    for num, freq in freq.items():
        if freq >= k:
            if freq > max_freq:
                max_freq = freq
                max_freq_num = num

    # Calculate the maximum number of operations
    if max_freq_num is None:
        return 0
    else:
        return (max_freq - 1) // (k - 1)

