def max_operations(l, r, k):
    if l == r:
        return 0

    # Find the largest power of k that is less than or equal to r
    max_power = 0
    while (k ** (max_power + 1)) <= r:
        max_power += 1

    # If max_power is 0, no multiple of k exists in the range [l, r]
    if max_power == 0:
        return 0

    # Calculate the number of operations needed
    return (r - l + 1) // (k ** max_power)

