    # Calculate the total number of lakes
    num_lakes = sum(heights[i][i] < 0 for i in range(n))

    # If there are no lakes, return 0
    if num_lakes == 0:
        return 0

    # Initialize the number of magic steps
    magic_steps = 0

    # Iterate over each possible submatrix
    for i in range(n):
        for j in range(n):
            for k in range(i, n):
                for l in range(j, n):
                    if k - i == l - j:
                        # Check if the submatrix has any lakes
                        if sum(heights[m][m] < 0 for m in range(i, k+1)) > 0:
                            # Increase the height of the main diagonal elements
                            for m in range(i, k+1):
                                heights[m][m] += 1
                            # Increment the number of magic steps
                            magic_steps += 1

    return magic_steps

