    # Count occurrences of each number in the first bag
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Check if the total number of elements is even
    if n % 2 != 0:
        return "NO"

    # Calculate the target value for each element in the first bag
    target = n // 2

    # Check if the difference between the target and the actual count of each element is even
    for num, freq in count.items():
        if (target - freq) % 2 != 0:
            return "NO"

    return "YES"

