def can_sort_satay_sticks(n, p):
    # Check if the permutation is already sorted
    if sorted(p) == p:
        return "YES"

    # Check if there are consecutive elements with a difference of 1
    for i in range(1, n):
        if abs(p[i] - p[i - 1]) != 1:
            return "NO"

    # If no consecutive elements have a difference of 1, check if the permutation can be sorted by swapping adjacent elements
    for i in range(1, n):
        if p[i] < p[i - 1]:
            # Find the smallest element greater than p[i]
            min_greater = min([j for j in range(i + 1, n) if p[j] > p[i]])
            # Swap p[i] and p[min_greater]
            p[i], p[min_greater] = p[min_greater], p[i]
            # Check if the permutation is now sorted
            if sorted(p) == p:
                return "YES"
            else:
                return "NO"

    return "NO"

