    # Check if the permutation is already sorted
    if p == list(range(1, len(p) + 1)):
        return "YES"

    # Find the longest increasing subsequence (LIS)
    lis_length = 0
    current_lis_end = 0

    for i in range(len(p)):
        if i > current_lis_end:
            lis_length += 1
            current_lis_end = i
        else:
            left, right = 0, current_lis_end
            while left < right:
                mid = (left + right) // 2
                if p[mid] < p[i]:
