def can_sort_p(permutation):
    # Check if the permutation is already sorted
    if permutation == list(range(1, len(permutation) + 1)):
        return "YES"

    # Check if there are any adjacent elements with a difference of 1
    for i in range(len(permutation) - 1):
        if abs(permutation[i] - permutation[i + 1]) != 1:
            return "NO"

    # If no adjacent elements have a difference of 1, check if it's possible to sort
    for i in range(len(permutation)):
        for j in range(i + 1, len(permutation)):
            if abs(permutation[j] - permutation[i]) == 1:
                # Try swapping the elements
                permutation[i], permutation[j] = permutation[j], permutation[i]
                # Check if the permutation is sorted
                if permutation == list(range(1, len(permutation) + 1)):
                    return "YES"
                # Unswap the elements to try another pair
                permutation[i], permutation[j] = permutation[j], permutation[i]

    return "NO"

