    if w < b:
        w, b = b, w

    # Calculate the maximum number of rows we can have
    max_rows = min(w + b // 2, 2 * (w + b))

    # Check if the total number of pins is enough to build the maximum frame
    if w + b >= 2 * max_rows * (max_rows - 1) // 2:
        return max_rows
    else:
        return max_rows - 1

