def can_win_game(n, s, r):
    def has_alternating(s):
        for i in range(len(s) - 1):
            if s[i] == s[i + 1]:
                return False
        return True

    def dfs(index, count):
        nonlocal has_alternating
        if count == n - 1:
            return has_alternating(s)

        for i in range(1, len(s)):
            if s[i] != s[i - 1]:
                s = s[:i] + r[index] + s[i + 1:]
                if dfs(i + 1, count + 1):
                    return True
                s = s[:i] + s[i + 1:]  # backtrack

        return False

    return "YES" if dfs(0, 0) else "NO"

