def calculate_manhattan_distances(n, m, r, c):
    total_distance = 0
    current_position = (r - 1) * m + c

    for i in range(current_position + 1, n * m + 1):
        next_position = (i // m) * m + (i % m)

        if next_position != current_position:
            dx = abs(next_position[0] - current_position[0])
            dy = abs(next_position[1] - current_position[1])
            total_distance += dx + dy

        current_position = next_position

    return total_distance

