        l, r = 0, len(arr) - 1
        while l <= r:
            mid = (l + r) // 2
            if arr[mid] == min_val:
                r = mid - 1
            else:
                l = mid + 1
        arr = [x for x in arr if x != min_val]
        count += 1
    return count

