from collections import Counter

def min_operations(arr, k):
    def find_min(l, r):
        if l == r:
            return arr[l]
        mid = (l + r) // 2
        left_min = find_min(l, mid)
        right_min = find_min(mid + 1, r)
        return min(left_min, right_min)

    def dfs(l, r, cnt):
        nonlocal ans
        if cnt > k:
            return
        if l > r:
            return
        if l == r:
            if cnt == k:
                ans = min(ans, cnt)
            return
        min_val = find_min(l, r)
        for i in range(l, r + 1):
            if arr[i] == min_val:
                dfs(i + 1, r, cnt + 1)
        dfs(l, r - 1, cnt + 1)

    n, k = map(int, sys.stdin.readline().split())
    arr = list(map(int, sys.stdin.readline().split()))
    ans = float('inf')
    dfs(0, n - 1, 0)
    return ans

