    n = m = 0
    count = {}

    # Count occurrences of each number
    for num in inputs:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Find the largest number of occurrences
    max_count = max(count.values())

    # Calculate the dimensions
    for num in count:
        if count[num] == max_count:
            n = num
            break

    m = len(inputs) // n

    return n, m

