import sys

def find_grid_dimensions(shuffled_inputs):
    n = len(shuffled_inputs)
    m = len(set(shuffled_inputs))

    # Find the maximum length of the subarray
    max_length = 0
    current_length = 0

    for i in range(n):
        if shuffled_inputs[i] == shuffled_inputs[0]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    return max_length, m

